import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useFormDraft } from '../hooks/useFormDraft';
import { validateProfile } from '../utils/validateProfile';
import PersonalInfoStep from './steps/PersonalInfoStep';
import { submitForm, getUserFormSubmissions } from '../services/firebaseService';
import { useAuth } from '../contexts/AuthContext';
import { signOutUser } from '../services/authService';

const MultiStepForm = () => {
  const { user, userId } = useAuth();
  const { formData, setFormData, draftStatus, clearDraft } = useFormDraft(userId);
  // The CV stays in memory; only its filename is persisted with the form answers.
  const [cvFile, setCVFile] = useState(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitMessage, setSubmitMessage] = useState('');
  const [submissions, setSubmissions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const formRef = useRef(null);
  const [submitAttempts, setSubmitAttempts] = useState(0);
  const validationErrors = submitAttempts ? validateProfile(formData, cvFile) : {};
  const errorCount = Object.keys(validationErrors).length;

  useEffect(() => {
    if (!submitAttempts) return;
    const firstInvalid = formRef.current?.querySelector('[aria-invalid="true"]:not([disabled]), [data-invalid="true"]');
    firstInvalid?.focus({ preventScroll: true });
    firstInvalid?.scrollIntoView?.({ block: 'center' });
  }, [submitAttempts]);

  const handleLogout = async () => {
    await signOutUser();
  };

  const loadSubmissions = useCallback(async () => {
    try {
      setLoading(true);
      setError('');
      const submissionsResult = await getUserFormSubmissions(userId);
      if (submissionsResult.success) {
        setSubmissions(submissionsResult.data);
      } else {
        setError(submissionsResult.message);
      }
    } catch (err) {
      setError('Failed to load submissions');
      console.error('Error loading submissions:', err);
    } finally {
      setLoading(false);
    }
  }, [userId]);

  useEffect(() => {
    loadSubmissions();
  }, [loadSubmissions]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (isSubmitting) return;
    setSubmitMessage('');
    setSubmitAttempts(attempts => attempts + 1);
    if (Object.keys(validateProfile(formData, cvFile)).length) return;
    setIsSubmitting(true);

    try {
      const result = await submitForm(formData, cvFile, userId);

      if (result.success) {
        setSubmitMessage('Form submitted successfully!');
        // Reset form
        clearDraft();
        setCVFile(null);
        setSubmitAttempts(0);
        // Reload submissions to show the new one
        loadSubmissions();
      } else {
        setSubmitMessage(result.message);
      }
    } catch (error) {
      setSubmitMessage('An error occurred. Please try again.');
      console.error('Submit error:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="container">
      <div className="form-container">
        <div className="form-heading">
          <div><p className="eyebrow">YOUR HPAIR PROFILE</p><h1>Let’s get to know you.</h1></div>
          <button 
            onClick={handleLogout}
            className="btn btn-secondary"
            style={{ fontSize: '14px', padding: '8px 16px' }}
          >
            Logout
          </button>
        </div>
        <p className="page-description">Tell us about yourself and how to reach you. Fields are required unless marked optional.</p>

        <div className="account-strip">
          <span>Signed in as <strong>{user.email}</strong></span>
        </div>

        <p className="draft-status" role="status" aria-live="polite">
          {draftStatus === 'restored'
            ? 'Your draft is restored. Please select your CV again before submitting.'
            : draftStatus === 'saved'
              ? 'Draft saved on this browser.'
              : draftStatus === 'unavailable'
                ? 'Draft saving is unavailable in this browser. Keep this page open to retain your answers.'
                : 'Your answers save automatically on this browser.'}
        </p>

        <form ref={formRef} noValidate autoComplete="off" onSubmit={handleSubmit} className="profile-form">
          <PersonalInfoStep 
            errors={validationErrors}
            formData={formData} 
            cvFile={cvFile}
            onCVChange={setCVFile}
            setFormData={setFormData} 
          />

          {errorCount > 0 && (
            <div className="validation-summary" role="status" aria-live="polite">
              <strong>A few details still need your attention.</strong>
              <p>Please check {errorCount === 1 ? 'the highlighted field' : `the ${errorCount} highlighted fields`} above. Your answers are still here.</p>
            </div>
          )}
          {submitMessage && (
            <div className={`submit-message ${submitMessage.includes('successfully') ? 'success' : 'error'}`} role="status">
              {submitMessage}
            </div>
          )}

          <div className="form-actions profile-actions">
            <button
              type="submit"
              className="btn btn-primary"
              disabled={isSubmitting}
            >
              {isSubmitting ? 'Submitting...' : 'Submit information'}
            </button>
          </div>
        </form>

        {/* Admin Panel - User's Submissions */}
        <details className="submission-history">
          <summary>Your previous submissions {!loading && !error && <span>{submissions.length}</span>}</summary>
          <p>View your submitted information below.</p>

          {!loading && !error && <div style={{ marginBottom: '20px', padding: '15px', backgroundColor: 'var(--color-surface-muted)', borderRadius: '8px' }}>
            <p><strong>Logged in as:</strong> {user.email}</p>
            <p><strong>Your submissions:</strong> {submissions.length}</p>
          </div>}

          <button 
            onClick={loadSubmissions}
            disabled={loading}
            className="btn btn-primary"
            style={{ marginBottom: '20px' }}
          >
            Refresh
          </button>

          {loading ? (
            <p>Loading submissions...</p>
          ) : error ? (
            <p role="status">
              {error}
            </p>
          ) : submissions.length === 0 ? (
            <p>There were no previous submissions.</p>
          ) : (
            <div className="submissions-list">
              {submissions.map((submission) => (
                <div key={submission.id} className="submission-item">
                  <div className="submission-header">
                    <h3>Submission #{submission.id.slice(-8)}</h3>
                    <span className="submission-date">
                      {formatDate(submission.submittedAt)}
                    </span>
                  </div>
              <div className="submission-details">
                <p><strong>Status:</strong> {submission.status === 'upload_failed'
                  ? 'Not submitted — upload or save failed'
                  : submission.status === 'uploading'
                    ? 'Submission not completed'
                    : (submission.status || 'submitted').replaceAll('_', ' ')}</p>
                <p><strong>Name:</strong> {submission.firstName} {submission.lastName}</p>
                {submission.cvName && <p><strong>CV filename:</strong> {submission.cvName}</p>}
                <p><strong>Date of Birth:</strong> {submission.dateOfBirth}</p>
                <p><strong>Gender:</strong> {submission.gender}</p>
              </div>
                </div>
              ))}
            </div>
          )}
        </details>
      </div>
    </div>
  );
};

const formatDate = (timestamp) => {
  if (!timestamp) return 'N/A';
  return new Date(timestamp.seconds * 1000).toLocaleString();
};

export default MultiStepForm;
